# -*- coding: utf-8 -*-
B=[
dict(a=1,z=3,star=2,
lit='「耶和華的宣告：到那時，人要把猶大諸王的骸骨、首領的骸骨、祭司的骸骨、先知的骸骨，和耶路撒冷居民的骸骨，都從他們的墳墓中取出來，攤在日頭、月亮和天上萬象之下，就是他們所愛、所事奉、所跟隨、所求問、所敬拜的。這些骸骨不再被收殮，不再被埋葬，必像糞土一樣留在地面。這惡家族所剩下的人，在我趕他們到的各處，寧可選擇死亡，也不選擇生命。這是萬軍之耶和華的宣告。」',
key=[('骸骨','H6106','atsmot','骨頭，這裡指屍骨；本段重複五次'),('諸王','H4428','malkhei','君王們'),('墳墓','H6913','miqivreihem','他們的墳墓'),('日頭','H8121','shemesh','太陽；古代近東崇拜的對象'),('死亡','H4194','mavet','死亡'),('生命','H2416','chayyim','生命、活著')],
gram=['**{H6106}**（骸骨）在這三節重複五次，依次是：君王、首領、祭司、先知、居民，從上到下，五個階層，同樣的結局。這是希伯來文的一種排比修辭，每一個階層都被點名。','**{H4194}** 與 **{H2416}**：「寧可選擇死亡，也不選擇生命」，是申命記三十章十九節的反轉：摩西說「揀選生命」，這裡說他們寧可揀選死。'],
exp=['這一章用一個令人**震驚**的畫面開頭：墳墓被打開，骸骨被拖出來，攤在日頭月亮之下。在古代近東，這是對一個民族最大的羞辱：不得安葬。敵人征服之後，常常挖掘墳墓，侮辱死者。約西亞王自己，也曾打開墳墓，焚燒偶像祭司的骸骨（王下二十三章十六節）。','這幅畫面的諷刺在於：骸骨被攤在**日、月、星辰**之下，就是他們生前所愛、所事奉、所跟隨、所求問、所敬拜的。五個動詞，一路排下去，像一份宗教的履歷表。神說：你們一輩子敬拜的，現在讓它們來看你們的結局吧。','三節補了一個最沉重的細節：留下來的人，寧可揀死不揀生。這是申命記的反面：摩西說「你要揀選生命」，這一代人揀選了死。**審判之後的人，連生存的意願，也失去了。**']),
dict(a=4,z=7,star=3,
lit='「你要對他們說：耶和華這樣說：人跌倒，不再起來嗎？人轉去，不再轉回嗎？為什麼這耶路撒冷的百姓，竟永遠背道呢？他們緊抓著詭詐，不肯回頭。我留心聽，沒有人說正直的話；沒有一個人為自己的惡後悔，說：我做了什麼呢？各人轉向自己的路，如同馬直闖戰場。天空中的鸛鳥知道牠的定期；斑鳩、燕子和白鶴，都守著牠們來的時候；我的百姓卻不知道耶和華的法則。」',
key=[('永遠','H5329','netsach','持續、永遠；「恆久背道」'),('詭詐','H8649','tarmit','欺騙、詭計'),('後悔','H5162','nikham','後悔、悔改'),('直闖','H7857','shotef','沖刷、猛衝'),('鸛鳥','H2624','chasidah','鸛；與「慈愛」同字根'),('法則','H4941','mishpat','公平、法則、判決')],
gram=['**{H2624}**：鸛鳥這個名字，與「忠愛」（hesed）同一字根，直譯是「忠誠的鳥」。鸛鳥年年依時遷徙，是忠於自己本分的象徵；這個名字，已經是一個提示。','**{H4941}**：「法則」（mishpat）在這裡的意思，不只是法律條文，而是神安排的次序。鳥有牠們的次序，人卻不知道自己的次序。'],
exp=['四、五節是兩個**反問**：人跌倒，不再起來嗎？人轉去，不再轉回嗎？答案本來是「當然要」。跌倒了就爬起來，走錯了就轉回來，這是常識。可是神問：為什麼這百姓，竟永遠背道？這是一個很傷心的問題：連最基本的常識，這群人也失去了。','六節有一個令人心驚的細節：「沒有一個人為自己的惡後悔，說：我做了什麼呢？」沒有人。不是少數人不悔改，而是連一個問「我做了什麼」的人都沒有。這與五章一節的搜索，是同一個結論。','七節是這一段最美的**比喻**：鸛鳥、斑鳩、燕子、白鶴，都知道自己的時令，牠們年年依時而來，從不遲到。可是神的百姓，卻不知道神的法則。**鳥有本能，人有自由；本能不會偏離，自由卻能偏離。**']),
dict(a=8,z=9,star=3,
lit='「你們怎麼說：我們有智慧，耶和華的律法與我們同在？看哪，其實文士的假筆，把它寫成了謊言。智慧人必蒙羞，驚惶，被捉拿；看哪，他們棄絕了耶和華的話，他們還有什麼智慧呢？」',
key=[('智慧人','H2450','chakhamim','有智慧的人'),('律法','H8451','torat','訓誨、律法；Torah'),('筆','H5842','et','筆、書寫的工具'),('文士','H5608','sofrim','抄寫者、書記'),('棄絕','H3988','ma\'asu','厭棄、拒絕'),('智慧','H2451','chokhmat','智慧')],
gram=['**{H5842}** 與 **{H5608}**：「筆」與「文士」連在一起；這是舊約中少有的一處直接批評「書寫」。這裡的「假筆」，解經家有三種看法，見議題。','**{H8451}**：「律法」就是 Torah，原意是「指引」。他們說「耶和華的律法與我們同在」，神說：你們有智慧嗎？棄絕了神的話，哪還有智慧可言？'],
exp=['這兩節直接指向**宗教的專業階層**：自稱有智慧、手中握著律法的人。他們說：我們有智慧，耶和華的律法在我們這裡。這句話聽起來沒有錯，可是神回答：看哪，文士的筆，成了假的。','「文士的假筆」，是整章最有爭議的一句，這裡的「筆」怎麼成了假的？學者提出不同的看法：有人認為，這是指文士抄寫、解釋律法時，扭曲了意思；有人認為，是指他們編寫的文書，為當權者背書；也有人認為，是指約西亞改革之後，大家以為手上有書就代表有神的話。三種理解，都指向同一個結論：**擁有經文，不等於順服經文。**','九節給了一個很重的判斷：「他們棄絕了耶和華的話，他們還有什麼智慧呢？」智慧的標準，不是知識的多寡，而是你與神的話的關係。**棄絕神的話的智慧，不叫智慧。**']),
dict(a=10,z=12,star=3,
lit='「所以，我要把他們的妻子給別人，把他們的田地給新的主人，因為他們從最小的到最大的，都一味貪求不義之財；從先知到祭司，個個行事虛假。他們輕輕地醫治我百姓的創傷，說：『平安了！平安了！』其實並沒有平安。他們行可憎的事，知道羞愧嗎？他們一點也不羞愧，也不知道臉紅。因此，他們必在仆倒的人中仆倒；我追討他們的時候，他們必被絆倒。這是耶和華說的。」',
key=[('貪婪','H1215','betsa','不義之財'),('虛假','H8267','sheqer','虛假、謊言；全書追蹤字'),('輕輕地','H7043','niqlah','輕率、草率'),('平安','H7965','shalom','平安、完整；全書追蹤字'),('羞愧','H954','bosh','羞愧、臉紅'),('追討','H6486','pequdatam','追討、查訪、降罰')],
gram=['**{H7043}**：「輕輕地」，這一節與六章十四節幾乎一字不差。這在耶利米書，不是抄寫錯誤，而是刻意的重複：神把同一句話，說了兩次。','**{H6486}**：「追討」與五章九節的「追討」（H6485）同字根，是神「眷顧、查訪」的字，用在審判時，是「親自來算帳」。'],
exp=['這三節幾乎是**六章十三至十五節的重播**：貪婪、虛假、輕輕忽忽的醫治、不知羞恥。同一段話，在六章與八章各出現一次，是這個信息的重量：神不嫌重複。有些話，說一次不夠。','神重複這段話，讓我們看見一件事：假平安的問題，不是偶發，而是**系統性的**。從小到大，從先知到祭司，都在說同樣的話。當一個社會習慣了說「平安了」，說真話的人反而成了麻煩。','十二節說：「他們一點也不羞愧，也不知道臉紅。」重複出現在六章十五節。**一個民族連羞愧都沒有了，是最深的病。**']),
dict(a=13,z=17,star=2,
lit='「耶和華的宣告：我要把他們收盡，葡萄樹上沒有葡萄，無花果樹上沒有果子，葉子也枯萎了；我所賜給他們的，都要離開他們。我們為什麼坐著不動呢？我們要聚集，進入堅固的城，在那裡靜默，因為耶和華我們的神使我們靜默，又給我們喝苦膽水，因為我們得罪了耶和華。我們盼望平安，卻沒有好處；盼望痊癒的時候，卻只有驚恐。從但傳來敵人戰馬的鼻息聲，他的壯馬嘶叫的聲音，全地都震動，因為他們來要吞滅這地和其中所有的，吞滅這城和城中的居民。看哪，我要打發蛇到你們中間，是不受咒語制伏的毒蛇，牠們必咬你們。這是耶和華的宣告。」',
key=[('收盡','H622','asof','收集、收盡'),('苦膽水','H7219','mei-rosh','有毒的水、苦水'),('但','H1835','mi-dan','但；北方的邊境'),('嘶叫','H4684','mitsholot','嘶鳴聲'),('毒蛇','H5175','nechashim','蛇'),('咒語','H3908','lachash','低語、咒語、符咒')],
gram=['**{H5175}**、**{H6848}**（蝮蛇、毒蛇）：兩種蛇並列，加上「不受咒語制伏」。古代近東有弄蛇的咒語，這裡說：這些蛇，沒有咒語可以制伏。','**{H1835}**：「但」是以色列最北端的支派。敵人的馬嘶聲，從最北方傳來，一路南下；這是從地理上，畫出災禍臨近的路線。'],
exp=['這段是一幅**荒涼的田園畫**：葡萄樹上沒有葡萄，無花果樹上沒有果子，連葉子也枯了。農業社會最怕的，就是這個：一年的收成，什麼都沒有。神說：我所賜給他們的，都要離開他們。','十四、十五節是百姓自己的聲音：我們為什麼坐著不動？我們躲進堅固城吧！可是接著他們承認：是耶和華使我們靜默，又給我們喝苦膽水，因為我們得罪了耶和華。這是一個令人訝異的**認罪**：連百姓也知道，這是因為得罪了神。可是知道，不等於回頭。他們的反應，是躲進堅固的城裡。','十六、十七節是聲音：但那裡傳來馬的鼻息與嘶鳴，全地震動。然後是蛇：不受咒語制伏的毒蛇。**有些敵人，是用辦法對付得了的；有些，沒有。**這是神給的最後一個畫面：你們一切的辦法，都用盡了。']),
dict(a=18,z=20,star=3,
lit='「我的憂愁無法醫治，我的心在我裡面昏沉。聽啊，我百姓的呼求聲，從遠方的地傳來：耶和華不在錫安嗎？錫安的王不在其中嗎？為什麼他們用雕刻的偶像和外邦的虛無，惹我發怒呢？麥秋過去了，夏天也完了，我們還沒有得救！」',
key=[('憂愁','H3015','yagon','憂愁、悲痛'),('無法醫治','H4010','mavligiti','無從慰解（字義不確定）'),('昏沉','H1742','davay','虛弱、昏沉、生病'),('呼求','H7775','shav\'at','呼求、哀號'),('虛無','H1892','havlei','虛空、氣息'),('得救','H3467','noshanu','被拯救')],
gram=['**{H4010}**：這個字在舊約只出現一次，字義不確定；有人解作「我的歡樂已逝」，有人解作「無從慰解」。無論怎麼理解，都是說：先知找不到任何能安慰自己的方法。','**{H3467}**（得救）：麥秋與夏令，是農業年度的兩個收割期；兩個都過了，卻沒有得救。這句話，是整章最令人心酸的一句：時間用完了，救恩沒有來。'],
exp=['這一段是**三個聲音**混在一起：先知的聲音（十八節）、百姓從遠方傳來的聲音（十九節上）、神的聲音（十九節下）。最令人心驚的，是百姓的問題：「耶和華不在錫安嗎？錫安的王不在其中嗎？」在最危急的時候，他們不確定神在不在。','神的回答，是一個反問：為什麼他們要用雕刻的偶像和外邦的虛無，惹我發怒？意思是：神不是不在，是你們把祂擠出去了。祂在，卻被你們用偶像取代了。','二十節是整章最**心酸**的一句：「麥秋已過，夏令已完，我們還未得救！」一年的兩個收成都錯過了，救恩沒有來。人在最後的期限過了之後才說「我們還沒有得救」，語氣中有失望，也有後悔。這提醒我們：**神的呼喚有它的時節，不要等到收割過了才開口。**']),
dict(a=21,z=22,star=3,
lit='「因我百姓的創傷，我也受了創傷；我哀痛，驚恐抓住了我。在基列沒有乳香嗎？在那裡沒有醫生嗎？為什麼我百姓的傷口，還不得癒合呢？」',
key=[('創傷','H7667','shever','破碎、創傷；全書追蹤字'),('受了創傷','H7665','hushbarti','我被打碎'),('哀痛','H6937','qadarti','變黑、哀痛'),('乳香','H6875','tsori','基列出產的香膏樹脂'),('基列','H1568','gil\'ad','約旦河東的山區'),('痊癒','H724','arukhah','新肉長出來；傷口癒合')],
gram=['**{H7667}** 與 **{H7665}**：同一字根（破碎）的名詞與動詞：「我百姓的破碎（shever），我也被打碎（hushbarti）」。先知不是旁觀者，他的名字就印在這個傷口上。','**{H724}**：這個字的原意是「長出新肉」。「為什麼我百姓的傷口，還不得癒合呢？」問的是：新肉為什麼長不出來？'],
exp=['最後兩節是整章最**溫柔，也最痛**的結尾。先知說：因我百姓的傷，我也受了傷。他不是站在傷口的旁邊，而是把自己放進傷口裡。這是耶利米最動人的地方：他是一個與百姓一同破碎的先知。','二十二節的三個問題，是整卷書最有名的幾句話：「在基列沒有乳香嗎？在那裡沒有醫生嗎？為什麼我百姓的傷口，還不得癒合呢？」基列是約旦河東的山區，以出產乳香聞名（創三十七章二十五節）。先知的意思是：藥有，醫生也有，為什麼病不好？','這三個問題，是**沒有答案的答案**：藥在，醫生也在，是病人不肯用。這與八章一至十二節連起來讀：百姓有律法，有先知，有祭司，有殿，可是傷口不癒。問題不在藥，在於人是否肯被醫治。後來，新約告訴我們，那位真正的醫生來了（太九章十二節）。']),
]
